ee:variables.ee:set-variable:
%dw 2.0
import secureToken, nowIst, ts, fmt from dwl::report
output application/java
var tooBig = sizeOf(vars.fileBytes) > (p('email.maxAttachmentBytes') as Number)
var expires = fmt(ts(nowIst()) + ("PT" ++ p('secureLink.validHours') ++ "H") as Period)
---
if (not tooBig) { method: "ATTACHMENT", link: null, expiresAt: null }
else {
  method: "SECURE_LINK",
  expiresAt: expires,
  link: p('secureLink.baseUrl') ++ "/api/downloads/" ++ secureToken(vars.runId, "SUBMISSION", expires, p('secure::secureLink.secret'))
}
